                return match;
            }
            const id = idMatch[1].trim();
            const expr = exprMatch[1].trim();
            const result = evaluateCalcExpression_ACU(expr, context);
            if (result.success) {
                calcVariables_ACU[id] = result.value;
                logDebug_ACU('[计算变量] 定义成功:', id, '=', result.value, '表达式:', expr);
                return '';
