            if (!normalized || seen.has(normalized))
                return;
            seen.add(normalized);
            files.push({
                path: normalized,
                references: [{ messageIndex, isolationKey }],
                role,
                messageIndex,
                isolationKey,
                sourceTableKey,
                manifestKey: normalized,
                checksum,
            });
        };
