        if (Array.isArray(chat)) {
            chat.forEach((message, messageIndex) => {
                const isolated = message?.TavernDB_ACU_IsolatedData;
                if (!isolated || typeof isolated !== 'object' || Array.isArray(isolated))
                    return;
