            backend: 'st-files',
            status: 'ready',
            indexId,
            chatKey,
            isolationKey,
            snapshotMessageId: options.snapshotMessageId,
            sourceTableKey,
            sourceTableName: options.sourceTableName,
            indexedAt,
            updatedAt: indexedAt,
