                mode: 'content_addressed_packs',
                chunkRefs: [],
                activeChunkKeys: chunks.map((chunk) => chunkKeysByChunkId.get(chunk.chunkId) || `chunk_${chunk.chunkId}`),
                packRefs: contentPackRefs,
            };
        }
