        }
        catch (error) {
            throw buildRollbackAwareError_ACU(error, await rollbackUploadedFiles_ACU(publicationFiles));
        }
        logSummaryVectorIndexIdentityEvent_ACU('debug', 'persist', 'prepared', {
            manifest: finalManifest,
            path: snapshotPath,
        });
        return { state, manifest: finalManifest, uploadedFiles: publicationFiles };
    }
    async function loadOneShardChunks_ACU(indexId, ref, options = {}) {
