                    issues.push({
                        severity: 'error',
                        code: 'checksum_mismatch',
                        path: file.path,
                        role: file.role,
                        messageIndex: file.messageIndex,
                        isolationKey: file.isolationKey,
                        chunkKey: file.chunkKey,
                        chunkId: file.chunkId,
                        rowKey: file.rowKey,
