        if (!manifest) {
            const v2 = await tryReadV2MirrorDisplayStats_ACU();
            if (v2) {
                return {
                    ...v2,
                    tombstoneRowCount: 0,
                    tombstoneChunkCount: 0,
                    externalTotalBytes: v2.externalTotalBytes,
                    cacheTotalBytes,
                    tempCacheBytes: tempCache.bytes,
                    tempCacheCount: tempCache.count,
