            const rowChunkTexts = buildRowChunkTexts_ACU(row.vectorSourceText, { sentenceCount: options.sentenceCount, chunkBySentence: options.chunkBySentence });
            rowChunkTexts.forEach((text, chunkIndex) => {
                chunkSources.push({
                    chunkId: `${row.rowKey}:chunk:${chunkIndex}`,
                    rowKey: row.rowKey,
                    rowIndex,
                    text,
                    sequence: sequenceBase + chunkSources.length,
                });
            });
        });
        if (chunkSources.length === 0) {
            return { rows: [], chunks: [] };
        }
        const plan = planEmbeddingBatches_ACU(chunkSources, {
            maxRowsPerRequest: options.maxRowsPerRequest,
            maxInputCharsPerRequest: options.maxInputCharsPerRequest,
        });
        const { embeddings } = await executeEmbeddingBatchPlan_ACU(plan, {
            maxConcurrentRequests: options.maxConcurrentRequests,
            requestEmbeddings: (input) => createEmbeddings_ACU({
                endpoint: options.embeddingEndpoint,
                apiKey: options.embeddingApiKey,
                model: options.embeddingModel,
                input,
            }),
        });
