                chunkId: source.chunkId,
                rowKey: source.rowKey,
                rowOrder: source.rowIndex,
                text: source.text,
                vector,
                sequence: source.sequence,
            });
            const ids = rowChunkIds.get(source.rowKey) || [];
            ids.push(source.chunkId);
            rowChunkIds.set(source.rowKey, ids);
        });
