            mergedData = guideMergeResult.data;
            // 与 V2 分支一致：隔离表键与结构 warning 透出给加载路径报告，不再静默丢弃。
            lastMergeQuarantinedSheetKeys = guideMergeResult.quarantinedSheetKeys;
            lastMergeWarnings = guideMergeResult.warnings;
        }
