            return;
        Object.keys(incrementalData).forEach(sheetKey => {
            if (!sheetKey.startsWith('sheet_') || !incrementalData[sheetKey])
                return;
            if (!lastMergeSourceInventory.has(sheetKey))
                lastMergeSourceInventory.set(sheetKey, '');
