                lastMergeWarnings = mergeResult.warnings;
                const orderedKeys = getSortedSheetKeys_ACU(mergeResult.data);
                return migrateContentNullToRowId(reorderDataBySheetKeys_ACU(mergeResult.data, orderedKeys));
            }
