    /**
     * 按分号拆分 SQL 语句（跳过字符串内的分号）
     */
    function splitSqlStatements(sql) {
        const statements = [];
        let current = '';
        let inString = false;
        let stringChar = '';
        for (let i = 0; i < sql.length; i++) {
            const char = sql[i];
            if (inString) {
                current += char;
                // 检查字符串结束（处理转义的引号 ''）
                if (char === stringChar) {
                    if (i + 1 < sql.length && sql[i + 1] === stringChar) {
                        // 转义的引号，跳过
                        current += sql[i + 1];
                        i++;
                    }
                    else {
                        inString = false;
                    }
                }
            }
            else if (char === "'" || char === '"') {
                inString = true;
                stringChar = char;
                current += char;
            }
            else if (char === ';') {
                const trimmed = current.trim();
                if (trimmed)
                    statements.push(trimmed);
                current = '';
            }
            else {
                current += char;
            }
        }
        // 最后一条语句（可能没有分号结尾）
        const trimmed = current.trim();
        if (trimmed)
            statements.push(trimmed);
        return statements;
    }
