        if (ru === 'AI' || ru === 'ASSISTANT' || rl === 'assistant')
            return 'assistant';
        if (ru === 'SYSTEM' || rl === 'system')
            return 'system';
        if (ru === 'USER' || rl === 'user')
            return 'user';
        return 'user';
    }
    const STRICT_JSON_PROMPT_LEGACY_TOKEN_DENYLIST_ACU = [
        'insertRow',
        'updateRow',
        'deleteRow',
        'tableId',
        'rowIndex',
    ];
