        const hits = new Set();
        messages.forEach((message) => {
            const content = String(message?.content || '');
            STRICT_JSON_PROMPT_LEGACY_TOKEN_DENYLIST_ACU.forEach((token) => {
                if (content.includes(token))
                    hits.add(token);
