    /** 冻结 v25：职责清单版；存量配置迁移时逐段匹配，不用当前生成器反推。 */
    function buildV25OneShotWorldSimulationAgentPrompt_ACU(name) {
        return buildV24OneShotWorldSimulationAgentPrompt_ACU(name).map(segment => {
