        const state = pendingByScope_ACU.get(scopeKey) || { all: false, sheetKeys: new Set() };
        if (pending.all)
            state.all = true;
        for (const sheetKey of pending.sheetKeys) {
            if (typeof sheetKey === 'string' && sheetKey.startsWith('sheet_'))
                state.sheetKeys.add(sheetKey);
        }
