    async function writeV2BoundaryCheckpointBeforePurge_ACU(chat, boundaryAnchorIndex, checkpointReason = 'compaction') {
        if (boundaryAnchorIndex < 0 || !chat[boundaryAnchorIndex] || chat[boundaryAnchorIndex].is_user) {
