                        if (comment.startsWith('TavernDB-ACU-') || comment.startsWith('重要人物条目') || comment.startsWith('总结条目')) {
                            return false;
                        }
                        // [新增] 过滤屏蔽词条目
                        if (isEntryBlocked_ACU(entry)) {
                            return false;
                        }
                        return true;
                    })
                        .map((entry) => entry.uid);
                    settingsChanged = true;
