                logWarn_ACU('自动合并总结检测失败:', e);
            }
            return { success: true, autoMergeTriggered, autoMergeSuccess, checkpointWarning };
        }
        catch (error) {
            // 破坏性清理尚未开始：异常原样抛出（可能是普通路径的配置/准入错误，或
            // 发生在清理之前的规划错误），不吞掉，由上层按既有方式处理。
            if (!refillCleanupStarted) {
                throw error;
            }
            const failureError = error?.message || String(error || '手动更新执行异常。');
            logError_ACU('[Manual Update] 执行过程中发生未处理异常:', error);
            return await failManualRefillSession(failureError);
        }
        finally {
            _set_manualExtraHint_ACU('');
            _set_isAutoUpdatingCard_ACU(false);
        }
    }

    const AUTO_FILL_SKIP_WARN_REASONS_ACU = new Set([
        'ambiguous_generated_ai_message',
        'generated_ai_message_not_materialized',
        'resolved_message_not_ai',
    ]);
    function logAutoFillSkip_ACU(reason, context = {}) {
        const { eventType, messageId, eventMessageId, chatKey, isolationKey, liveIsolationKey, lastGenerationType, aiFloorCount, capturedChatLength, capturedAiFloorCount, liveChatLength, liveAiFloorCount, resolvedMessageIndex, candidateIndexes, inFlight, preconditionReason, } = context;
        const log = AUTO_FILL_SKIP_WARN_REASONS_ACU.has(reason) ? logWarn_ACU : logDebug_ACU;
        log('[AutoFill] Trigger skipped', {
            reason,
            eventType,
            messageId,
            eventMessageId,
            chatKey,
            isolationKey,
            liveIsolationKey,
            lastGenerationType,
            aiFloorCount,
            capturedChatLength,
            capturedAiFloorCount,
            liveChatLength,
            liveAiFloorCount,
            resolvedMessageIndex,
            candidateIndexes,
            inFlight,
            preconditionReason,
        });
    }

    function buildAutoUpdateProgressLabel_ACU(event) {
        if (Number.isFinite(event.currentBatch) && Number.isFinite(event.totalBatches)) {
            return `第 ${event.currentBatch}/${event.totalBatches} 批`;
        }
        return '当前批次';
    }
    function buildAutoUpdateProgressMessage_ACU(event) {
        const batchLabel = buildAutoUpdateProgressLabel_ACU(event);
        switch (event.phase) {
            case 'preparing':
                return `${batchLabel}：准备AI输入...`;
            case 'calling_ai':
                return `${batchLabel}：第 ${event.attempt || 1}/${event.maxRetries || 1} 次调用AI进行增量更新...`;
            case 'parsing':
                return `${batchLabel}：解析并应用AI返回的更新...`;
            case 'saving':
                return `${batchLabel}：正在将更新后的数据库保存到聊天记录...`;
            case 'chunk_done':
                return `${batchLabel}：分块处理成功...`;
            case 'complete':
                return `${batchLabel}：数据库增量更新成功！`;
            case 'retry':
                return `${batchLabel}：第 ${event.attempt || 1}/${event.maxRetries || 1} 次尝试失败，5秒后重试...${event.message ? ` (${event.message})` : ''}`;
            case 'error':
                return `${batchLabel}：错误：更新失败。`;
            default:
                return `${batchLabel}：正在处理...`;
        }
    }
    async function refreshRuntimeDataAndNotifyAfterAutoUpdate_ACU() {
        const data = getStorageProvider().getCurrentData() || currentJsonTableData_ACU;
        if (data) {
            await updateReadableLorebookEntry_ACU(true, false, null, data);
        }
        try {
            topLevelWindow_ACU.AutoCardUpdaterAPI?._notifyTableUpdate?.();
        }
        catch (_) { }
    }
    function handleAutoGroupedProgressEvent_ACU(event, progressTask) {
        const message = buildAutoUpdateProgressMessage_ACU(event);
        progressTask?.update(message);
        switch (event.phase) {
            case 'complete':
                if (typeof updateCardUpdateStatusDisplay_ACU === 'function')
                    updateCardUpdateStatusDisplay_ACU();
