        catch (error) {
            logWarn_ACU('[剧情推进] 伪装楼层创建失败，恢复原有发送流程:', error);
            try {
                removeBlock?.();
            }
            catch { /* ignore */ }
            try {
                $nodes?.remove();
            }
            catch { /* ignore */ }
