                    at,
                    metrics: {
                        sourceFromId: fromId,
                        sourceThroughId: throughId,
                        beforeTokens: 0,
                        afterTokens: 0,
                        fixedPromptTokens: 0,
                        reportTokens: 0,
                        targetTokens: 0,
                        triggerTokens: 0,
                        droppedMessages: snapshot.messages.length,
                        droppedTurns: turns.size,
                        degraded: false,
