                snapshot: source,
                activeMark: expectedMark,
                triggerTokens: budgetTokens,
                fixedPromptTokens: overheadTokens,
                ...(preparedMessages ? { preparedMessages } : {}),
                countTokens: counter,
                semanticAdapter,
            });
