                        const toolOk = results.every(result => result.status === 'ok' || result.status === 'empty');
                        updateWorldSimulationSession_ACU(input.identity.chatIdentity, toolEntryId, {
                            title: toolOk ? `资料读取完成（${results.length} 项）` : '资料读取部分失败',
