                                promptContext: requestContext,
                                registry: input.registry,
                                tools: input.tools,
                                writeSql: input.writeSql,
                                readCurrent: input.readCurrent,
                                readFieldSnapshot: input.readFieldSnapshot,
                                isCurrent: input.isCurrent,
