        }
        const written = await writeCurrentChatFillMode_ACU(current.mode);
        if ('reason' in written)
            return { recorded: false, reason: written.reason, ...(written.error ? { error: written.error } : {}) };
        return { recorded: true, mode: current.mode };
    }

