                                    if (hydrated.ok) {
                                        logDebug_ACU('[SQLite] CHAT_CHANGED: snapshot hydrate 完成');
                                    }
                                    else if (hydrated.failureCode === 'stale_load_discarded') {
                                        logDebug_ACU(`[SQLite] CHAT_CHANGED: snapshot 身份漂移（${hydrated.failureCode}），回退冷 reload。`);
                                        try {
                                            await reloadStorageProvider();
                                        }
                                        catch (e) {
                                            logError_ACU(`[SQLite] CHAT_CHANGED: 冷 reload 失败: ${e?.message}`);
                                        }
                                    }
                                    else {
                                        // provider_fallback（SQLite hydrate 失败已自动回退 native）或
                                        // provider_load_failed：保持 hydrate 返回的 fallback 状态机。
                                        logError_ACU(`[SQLite] CHAT_CHANGED: snapshot hydrate 失败: ${hydrated.failureCode || 'unknown'}${hydrated.error ? `: ${hydrated.error}` : ''}`);
                                    }
                                }
                                else {
                                    logDebug_ACU('[SQLite] CHAT_CHANGED: merged refresh 未产出可用 canonical（degraded/空数据），回退冷 reload。');
                                    try {
                                        await reloadStorageProvider();
                                    }
                                    catch (e) {
                                        logError_ACU(`[SQLite] CHAT_CHANGED: 数据库重建失败: ${e?.message}`);
                                    }
                                }
                            }
                            // 新对话（无表格数据）自动启用经典表格；必须在表格数据刷新之后、且刷新未降级时执行。
                            if (refreshResult && !refreshResult.degraded
                                && (!scheduledChatIdentifier_ACU || currentChatFileIdentifier_ACU === scheduledChatIdentifier_ACU)) {
                                // 先为未记录的对话固定填表模式（新对话取偏好模式），后续自动启用按该对话记录推导。
                                try {
                                    const recorded = await ensureCurrentChatFillModeRecorded_ACU();
                                    if ('reason' in recorded && recorded.reason === 'save_failed') {
                                        logWarn_ACU(`[填表模式] 对话填表模式记录保存失败，本轮按偏好模式运行: ${recorded.error || 'unknown'}`);
                                    }
                                }
                                catch (recordError) {
                                    logWarn_ACU('[填表模式] 对话填表模式记录异常，本轮按偏好模式运行:', recordError);
                                }
                                try {
                                    const autoEnable = await autoEnableFlightModeForNewChatIfNeeded_ACU();
                                    if (autoEnable.attempted && !autoEnable.result.ok) {
                                        showUiSurfaceToast_ACU({
                                            kind: 'warning',
                                            text: `新对话自动启用经典表格失败（${autoEnable.result.reason || 'unknown'}），本轮沿用旧填表方案。`,
                                        });
                                    }
                                }
                                catch (autoEnableError) {
                                    logWarn_ACU('[填表模式] 新对话自动启用经典表格异常，本轮沿用旧填表方案:', autoEnableError);
                                }
                            }
                            // [交火向量索引] 聊天数据刷新完成后，预热当前聊天对应的外置分片缓存。
                            // 注意：必须放在 refreshMergedDataAndNotifyWithUI_ACU 之后，否则可能读取到旧聊天的 manifest。
                            const vectorCacheResult = await preloadSummaryVectorIndexCacheForCurrentChat_ACU();
                            logDebug_ACU(`[交火向量索引] CHAT_CHANGED 缓存预热结果：success=${vectorCacheResult.success}, skipped=${vectorCacheResult.skipped === true}, reason=${vectorCacheResult.reason || 'none'}, chunks=${vectorCacheResult.chunkCount}, indexId=${vectorCacheResult.indexId || 'none'}`);
                            if (shouldRebuildSummaryVectorIndexWithUI_ACU(vectorCacheResult.reason)) {
                                try {
                                    await rebuildCurrentSummaryVectorIndexWithUI_ACU();
                                }
                                catch (rebuildError) {
                                    logWarn_ACU('[交火向量索引] 失效索引已删除，但普通重建路径执行失败:', rebuildError);
                                }
                            }
                            else if (vectorCacheResult.success && !vectorCacheResult.skipped) {
                                // spv9.2 源文本升级：旧格式索引在后台静默重建，不阻塞 CHAT_CHANGED 后续步骤。
                                void rebuildOutdatedSummaryVectorIndexInBackground_ACU().catch((error) => {
                                    logWarn_ACU('[交火向量索引] 旧源文本索引后台重建异常:', error);
                                });
                            }
                            const shouldRestoreFlushQueue = !String(vectorCacheResult.reason || '').startsWith('external_files_missing_state_clear');
                            if (!shouldRestoreFlushQueue) {
                                logWarn_ACU(`[交火向量索引] CHAT_CHANGED 跳过 flush 队列恢复：missing-file 状态清理未完成或已进入重建恢复，reason=${vectorCacheResult.reason || 'unknown'}`);
                            }
                            if (shouldRestoreFlushQueue)
                                try {
                                    const restoredFlushCount = await restoreSummaryVectorIndexFlushQueueForCurrentChat_ACU();
                                    if (restoredFlushCount > 0) {
                                        logDebug_ACU(`[交火向量索引] CHAT_CHANGED 已恢复防抖归档队列：count=${restoredFlushCount}`);
                                    }
                                }
                                catch (restoreFlushError) {
                                    logWarn_ACU('[交火向量索引] CHAT_CHANGED 恢复防抖归档队列失败:', restoreFlushError);
                                }
                            // S0-4：聊天切换加载完成后捕获 checkpoint 保管库（删楼恢复的影子基线）。
                            try {
                                captureCheckpointVaultForCurrentChat_ACU();
                            }
                            catch (vaultError) {
                                logWarn_ACU(`[删楼守卫] CHAT_CHANGED 保管库捕获失败: ${vaultError?.message}`);
                            }
                            logDebug_ACU('ACU: Chat data reload and UI refresh triggered after chat change (Delayed).');
                        }
                        catch (chatChangedError) {
                            const message = chatChangedError instanceof Error ? chatChangedError.message : String(chatChangedError);
                            logError_ACU('ACU: CHAT_CHANGED 延迟刷新失败（已尝试全部兼容读取层）:', chatChangedError);
                            showUiSurfaceToast_ACU({
                                kind: 'error',
                                text: `表格数据加载失败：${message}`,
                                action: {
                                    label: '打开数据管理',
                                    onClick: async () => { await getUiSurface_ACU()?.openSettings?.(); },
                                },
                            });
                        }
                    }, 1200); // 增加延迟到1200ms，给SillyTavern更多的DOM渲染和上下文切换时间
                });
                // [触发门控] 记录“用户真实发送”的消息ID，用于剧情推进触发判定
                if (SillyTavern_API_ACU.eventTypes.MESSAGE_SENT) {
                    SillyTavern_API_ACU.eventSource.on(SillyTavern_API_ACU.eventTypes.MESSAGE_SENT, (messageId) => {
                        try {
                            recordLastUserSend_ACU(messageId);
                        }
                        catch (e) { }
                    });
                }
                // [触发门控] 捕捉“用户发送意图”：使用 capture 钩子，确保先于酒馆自身发送逻辑执行
                installSendIntentCaptureHooks_ACU();
                // [触发门控] 记录最近一次生成的上下文（用于过滤 quiet/后台生成导致的误触发）
                if (SillyTavern_API_ACU.eventTypes.GENERATION_STARTED) {
                    SillyTavern_API_ACU.eventSource.on(SillyTavern_API_ACU.eventTypes.GENERATION_STARTED, (type, params, dryRun) => {
                        try {
                            // 终止只作用于当次填表。新一轮宿主生成必须清掉残留，否则评估闸永久 user_aborted。
                            _set_wasStoppedByUser_ACU(false);
                            const context = recordGenerationContext_ACU(type, params, dryRun);
                            bindContinuationInternalAiGenerationStarted_ACU(context.seq);
                            bindWorldSimulationInternalAiGenerationStarted_ACU(context.seq);
                            // 宿主的 GENERATION_STARTED 通常在发送点击返回后的微任务里才送达，同步配对必然错过；
                            // 对非 quiet/非 dryRun/非自动触发的生成开放宽松认领（spv8.9.2 状态法），桥内部只在
                            // 存在未绑定序列号的等待轮时才会认领。
                            const quietLike = isQuietLikeGeneration_ACU(type, params);
                            getContinuationHostGenerationBridge_ACU()?.onGenerationStarted(context.seq, {
                                allowOrdinaryLooseClaim: !dryRun && !quietLike && !params?.automatic_trigger,
                                automaticTrigger: Boolean(params?.automatic_trigger),
                                quietLike,
                                dryRun: Boolean(dryRun),
                            });
                        }
                        catch (e) { }
                    });
                }
                if (SillyTavern_API_ACU.eventTypes.GENERATION_STOPPED) {
                    SillyTavern_API_ACU.eventSource.on(SillyTavern_API_ACU.eventTypes.GENERATION_STOPPED, () => {
                        try {
                            const discarded = discardLatestGenerationContext_ACU();
                            // 被中止的生成不会再有 GENERATION_ENDED；通知桥把等待中的续写轮转为可重试，避免卡死。
                            void getContinuationHostGenerationBridge_ACU()?.onGenerationStopped(discarded?.seq);
                        }
                        catch (e) { }
                    });
                }
                if (SillyTavern_API_ACU.eventTypes.GENERATION_ENDED) {
                    const onGenerationEnded = (message_id) => {
                        logDebug_ACU(`ACU GENERATION_ENDED event for message_id: ${message_id}`);
                        const generationContext = consumeGenerationContextForEnded_ACU();
                        const internalRequest = consumeContinuationInternalAiGenerationEnded_ACU(generationContext?.seq);
                        if (internalRequest) {
                            logDebug_ACU(`ACU 忽略 continuation 内部 ${internalRequest.source} GENERATION_ENDED: ${internalRequest.requestId}`);
                            return;
                        }
                        const simulationInternalRequest = consumeWorldSimulationInternalAiGenerationEnded_ACU(generationContext?.seq);
                        if (simulationInternalRequest) {
                            logDebug_ACU(`ACU 忽略格林推演内部 ${simulationInternalRequest.role} GENERATION_ENDED: ${simulationInternalRequest.requestId}`);
                            return;
                        }
                        const continuationBridge = getContinuationHostGenerationBridge_ACU();
                        // 宽松认领只对"会产生正文楼层"的生成开放：quiet/dryRun/自动触发生成不许认领，
                        // 否则会误杀等待中的续写轮。判定复用自动填表的生成门控。
                        const quietLike = generationContext ? isQuietLikeGeneration_ACU(generationContext.type, generationContext.params) : false;
                        const automaticTrigger = Boolean(generationContext?.params?.automatic_trigger);
                        const continuationEventContext = {
                            allowOrdinaryLooseClaim: !generationContext || (!generationContext.dryRun && !quietLike && !automaticTrigger),
                            automaticTrigger,
                            quietLike,
                            dryRun: Boolean(generationContext?.dryRun),
                        };
                        if (continuationBridge?.claimsGenerationEnded(generationContext?.seq, continuationEventContext)) {
                            // 桥只负责续写轮次的归属确认/循环标签校验/自动续下一轮，不再短路后续管线：
                            // 填表与正文优化由下方常规意图派发按各自的判定独立触发（解耦，见 spv 讨论）。
                            // 桥因标签缺失删楼重试时，常规管线的楼层解析（唯一候选 + 有界物化等待）与
                            // evaluateNewMessageAction 的 resolved_message_not_ai 防御会自然跳过该楼。
                            void continuationBridge.onGenerationEnded(message_id, generationContext?.seq, continuationEventContext);
                        }
                        // [触发修复] 原子捕获完整意图快照：事件参数只作为锚点，不承诺是 AI 数组下标。
                        // makeFirst 可能早于宿主把本轮 AI 回复追加进 chat，因此必须记录捕获时边界，
                        // 由 resolveGeneratedAiMessageIndex_ACU 在防抖回调中按唯一候选规则解析。
                        const chatAtCapture = SillyTavern_API_ACU?.chat || [];
                        const eventMessageId = typeof message_id === 'number' && Number.isInteger(message_id)
                            ? message_id
                            : undefined;
                        const autoFillIntent = eventMessageId !== undefined
                            ? {
                                eventMessageId,
                                chatKey: currentChatFileIdentifier_ACU,
                                isolationKey: getCurrentIsolationKey_ACU(),
                                capturedAt: Date.now(),
                                capturedChatLength: chatAtCapture.length,
                                capturedAiFloorCount: chatAtCapture.filter((m) => m && !m.is_user && m?.extra?.type !== 'narrator').length,
                                // generationSeq 仅在 generationGate 已产生过生成上下文时可靠；否则不假造。
                                generationSeq: generationGate_ACU.generationSeq > 0 ? generationGate_ACU.generationSeq : undefined,
                            }
                            : undefined;
                        // [触发修复] generationContext 缺失（60s TTL 过期或共享栈被其他生成错配弹走）不再静默跳过：
                        // 与自动填表门控语义对齐（shouldProcessAutoTableUpdateForGenerationEnded_ACU 对 null 上下文放行），
                        // 只在确证 dryRun/quiet/自动触发生成，或格林推演内部调用仍在途（本次上下文可能已被内部事件错配消费）时放弃。
                        const simulationInternalInFlight = hasWorldSimulationInternalAiInflight_ACU();
                        const simulationContextBlocked = !!generationContext && (generationContext.dryRun || quietLike || automaticTrigger);
                        // 仪表盘开关同时门控后台自动触发；缺失配置按关闭处理，不影响其他正文完成管线。
                        if (settings_ACU.worldSimulationPageEnabled === true && !simulationContextBlocked && !simulationInternalInFlight && eventMessageId !== undefined) {
                            const simulationIntent = createWorldSimulationCompletionIntentForCurrentChat_ACU(eventMessageId, currentChatFileIdentifier_ACU, getCurrentIsolationKey_ACU(), generationContext?.seq);
                            void getWorldSimulationRuntime_ACU().handleAssistantCompletion(simulationIntent).catch(error => {
                                logWarn_ACU(`格林推演自动触发失败：${error instanceof Error ? error.message : String(error)}`);
                            });
                        }
                        else {
                            logDebug_ACU(`格林推演自动触发跳过：${settings_ACU.worldSimulationPageEnabled !== true ? 'feature_disabled' : eventMessageId === undefined ? 'no_event_message_id' : simulationInternalInFlight ? 'internal_inflight' : 'quiet_or_background_generation'}`);
                        }
                        if (shouldProcessAutoTableUpdateForGenerationEnded_ACU(generationContext)) {
                            handleNewMessageDebounced_ACU('GENERATION_ENDED', autoFillIntent);
                        }
                        else {
                            logDebug_ACU('ACU: Skip auto table update due to quiet/background generation.');
                            logAutoFillSkip_ACU('quiet_or_background_generation', {
                                eventType: 'GENERATION_ENDED',
                                messageId: message_id,
                                eventMessageId: message_id,
                                chatKey: currentChatFileIdentifier_ACU,
                                isolationKey: getCurrentIsolationKey_ACU(),
                                capturedChatLength: chatAtCapture.length,
                                capturedAiFloorCount: chatAtCapture.filter((m) => m && !m.is_user && m?.extra?.type !== 'narrator').length,
                                lastGenerationType: generationGate_ACU.lastGeneration?.type,
                            });
                        }
                    };
                    if (typeof SillyTavern_API_ACU.eventSource.makeFirst === 'function') {
                        SillyTavern_API_ACU.eventSource.makeFirst(SillyTavern_API_ACU.eventTypes.GENERATION_ENDED, onGenerationEnded);
                    }
                    else {
                        SillyTavern_API_ACU.eventSource.on(SillyTavern_API_ACU.eventTypes.GENERATION_ENDED, onGenerationEnded);
                    }
                }
                // [剧情推进] 拦截用户输入进行剧情规划
                if (SillyTavern_API_ACU.eventTypes.GENERATION_AFTER_COMMANDS) {
                    SillyTavern_API_ACU.eventSource.on(SillyTavern_API_ACU.eventTypes.GENERATION_AFTER_COMMANDS, async (type, params, dryRun) => {
                        // 前置过滤（纯 UI/宿主层判断）
                        if (params?._qrf_processed_by_hook)
                            return;
                        const shouldProcessSummaryVectorIndex = shouldProcessSummaryVectorIndexForGeneration_ACU(type, params, dryRun);
                        const shouldProcessPlot = shouldProcessPlotForGeneration_ACU(type, params, dryRun);
                        const shouldEnsureInitialSeed = !dryRun
                            && type !== 'regenerate'
                            && !params?.automatic_trigger
                            && !isQuietLikeGeneration_ACU(type, params)
                            && (isRecentUserSendIntent_ACU() || shouldProcessSummaryVectorIndex || shouldProcessPlot);
                        if (shouldEnsureInitialSeed) {
                            await ensureInitialSeedCheckpointBeforeGeneration_ACU('generation_after_commands_before_ai', { allowPendingFirstUserMessage: true });
                        }
                        if (!shouldProcessSummaryVectorIndex && !shouldProcessPlot)
                            return;
                        if (shouldProcessSummaryVectorIndex) {
                            try {
                                const chatForSummaryIndex = SillyTavern_API_ACU.chat;
                                const lastUserText = (chatForSummaryIndex?.length && chatForSummaryIndex[chatForSummaryIndex.length - 1]?.is_user)
                                    ? String(chatForSummaryIndex[chatForSummaryIndex.length - 1].mes || '')
                                    : String(getSendTextareaValue_ACU() || params?.prompt || '');
                                const summaryVectorResult = await processSummaryVectorIndexBeforeGenerationWithUI_ACU({ userInput: lastUserText, source: 'generation_after_commands' });
                                logDebug_ACU(`[交火模式纪要索引] GENERATION_AFTER_COMMANDS 发送前处理完成：success=${summaryVectorResult.success}, skipped=${summaryVectorResult.skipped === true}, reason=${summaryVectorResult.reason || 'none'}, keywords=${summaryVectorResult.keywordCount ?? 0}, injected=${summaryVectorResult.injectedCount ?? 0}`);
                            }
                            catch (error) {
                                logWarn_ACU('[交火模式纪要索引] 发送前注入失败，继续原始生成:', error);
                            }
                        }
                        if (!shouldProcessPlot)
                            return;
                        if (type === 'regenerate' || isProcessing_Plot_ACU)
                            return;
                        // [去重] 若同一文本刚被 TavernHelper.generate 钩子处理过，跳过
                        try {
                            const lastMsgText = (SillyTavern_API_ACU.chat?.length && SillyTavern_API_ACU.chat[SillyTavern_API_ACU.chat.length - 1]?.is_user)
                                ? (SillyTavern_API_ACU.chat[SillyTavern_API_ACU.chat.length - 1].mes || '')
                                : '';
                            const boxText = String(getSendTextareaValue_ACU() || '');
                            if (shouldSkipPlotIntercept_ACU(String(lastMsgText)) || shouldSkipPlotIntercept_ACU(boxText)) {
                                logDebug_ACU('[剧情推进] Skip GENERATION_AFTER_COMMANDS due to recent TavernHelper.generate interception.');
                                return;
                            }
                        }
                        catch (e) { }
                        const chat = SillyTavern_API_ACU.chat;
                        if (!chat || chat.length === 0)
                            return;
                        // ── 策略1：已有用户消息 ──
                        const lastMessageIndex = chat.length - 1;
                        const lastMessage = chat[lastMessageIndex];
                        // [重构] 调用 service 层策略1编排
                        const s1 = await orchestrateAfterCommandsStrategy1_ACU(lastMessage, lastMessageIndex, runOptimizationLogicWithUI_ACU);
                        if (s1.action !== 'no_match') {
                            // 策略1匹配，根据结果做 UI 操作
                            switch (s1.action) {
                                case 'aborted':
                                    if (s1.manual) {
                                        // 停止生成
                                        try {
                                            if (SillyTavern_API_ACU && typeof SillyTavern_API_ACU.stopGeneration === 'function')
                                                SillyTavern_API_ACU.stopGeneration();
                                            else if (window.SillyTavern?.stopGeneration)
                                                window.SillyTavern.stopGeneration();
                                        }
                                        catch (e) { }
                                        // 删除刚创建的用户消息
                                        try {
                                            const chatNow = SillyTavern_API_ACU.chat;
                                            const lastNow = chatNow?.length ? chatNow[chatNow.length - 1] : null;
                                            if (lastNow && lastNow.is_user && String(lastNow.mes || '') === String(s1.originalMessage || '')) {
                                                if (typeof SillyTavern_API_ACU.deleteLastMessage === 'function')
                                                    await SillyTavern_API_ACU.deleteLastMessage();
                                                else if (window.SillyTavern?.deleteLastMessage)
                                                    await window.SillyTavern.deleteLastMessage();
                                            }
                                        }
                                        catch (e) { }
                                        // 恢复输入框
                                        try {
                                            setSendTextareaValue_ACU(s1.restoreText || '');
                                        }
                                        catch (e) { }
                                    }
                                    break;
                                case 'planned':
                                    // 写回 params 和消息对象
                                    params.prompt = s1.finalMessage;
                                    lastMessage.mes = s1.finalMessage;
                                    SillyTavern_API_ACU.eventSource.emit(SillyTavern_API_ACU.eventTypes.MESSAGE_UPDATED, lastMessageIndex);
                                    if (getSendTextareaValue_ACU() === s1.originalMessage)
                                        setSendTextareaValue_ACU('');
                                    break;
                                // 'skipped' — 不做额外操作
                            }
                            return; // 策略1匹配，不再执行策略2
                        }
                        // ── 策略2：输入框文本 ──
                        // shouldProcessPlot 是本次 GENERATION_AFTER_COMMANDS 事件开始时捕获的授权。
                        // 交火召回可能耗时超过 USER_SEND_TRIGGER_TTL_MS_ACU；这里不能再用 TTL 二次否决，
                        // 否则会出现“交火已覆盖纪要索引，但剧情推进被跳过并直接正文生成”的断链。
                        if (!shouldProcessPlot && !isRecentUserSendIntent_ACU())
                            return;
                        const textInBox = String(getSendTextareaValue_ACU() || '');
                        // [伪装发送] 宿主要等本监听结束才读取发送框并让用户楼层入楼。规划期间先在聊天区显示
                        // 伪装的用户楼层与“思考中”AI 楼层（纯 DOM），并清空发送框；无论规划结果如何，
                        // 结束时都把文本交还发送框（成功为规划结果，其余为原文），宿主随后按原生流程入楼并生成。
                        const disguise = textInBox.trim() ? beginPlotPendingDisguise_ACU(textInBox) : null;
                        let textForHost = textInBox;
                        try {
                            // [重构] 调用 service 层策略2编排
                            const s2 = await orchestrateAfterCommandsStrategy2_ACU(textInBox, runOptimizationLogicWithUI_ACU);
                            switch (s2.action) {
                                case 'aborted':
                                    if (s2.manual) {
                                        try {
                                            if (SillyTavern_API_ACU && typeof SillyTavern_API_ACU.stopGeneration === 'function')
                                                SillyTavern_API_ACU.stopGeneration();
                                            else if (window.SillyTavern?.stopGeneration)
                                                window.SillyTavern.stopGeneration();
                                        }
                                        catch (e) { }
                                    }
                                    break;
                                case 'planned':
                                    textForHost = s2.finalMessage;
                                    if (!disguise)
                                        setSendTextareaValue_ACU(s2.finalMessage);
                                    try {
                                        params.prompt = s2.finalMessage;
                                    }
                                    catch (e) { }
                                    break;
                            }
                        }
                        finally {
                            disguise?.release(textForHost);
                        }
                        // 消费掉本次发送意图
                        generationGate_ACU.lastUserSendIntentAt = 0;
                    });
                }
                const chatModificationEvents = ['MESSAGE_DELETED', 'MESSAGE_SWIPED'];
                chatModificationEvents.forEach(evName => {
                    if (SillyTavern_API_ACU.eventTypes[evName]) {
                        SillyTavern_API_ACU.eventSource.on(SillyTavern_API_ACU.eventTypes[evName], async (data) => {
                            logDebug_ACU(`ACU ${evName} event detected. Triggering data reload and merge from chat history.`);
                            scheduleChatMutationRefresh_ACU(evName === 'MESSAGE_DELETED' ? 'chat_modified_deleted' : 'chat_modified_swiped');
                        });
                    }
                });
                logDebug_ACU('ACU: All event listeners attached using eventSource.');
            }
            else {
                logWarn_ACU('ACU: Could not attach event listeners because eventSource or eventTypes are missing.');
            }
            // [新增] 移除公用的手动更新按钮，改为两个独立的手动更新按钮
            // if (typeof eventOnButton === 'function') {
            //     eventOnButton('更新数据库', handleManualUpdateCard_ACU);
            //     logDebug_ACU(
            //         "ACU: '更新数据库' button event registered with global eventOnButton.",
            //     );
            // } else {
            //     logWarn_ACU("ACU: Global eventOnButton function is not available.");
            // }
            // 修复：移除启动时的状态重置调用。现在完全依赖于SillyTavern加载后触发的第一个CHAT_CHANGED事件来初始化，避免了竞态条件。
            // [新增修复]：为了解决作为角色脚本加载时可能错过初始CHAT_CHANGED事件的问题，
            // 我们在初始化时主动获取一次当前聊天信息并进行设置。
            // 这确保了无论脚本何时加载，都能正确初始化。
            // [修复] 添加轮询重试机制：如果 chatId 暂时不可用，持续轮询直到可用
            const initWithChatId = async (chatId) => {
                logDebug_ACU(`ACU: Initializing with current chat on load: ${chatId}`);
                await resetScriptStateForNewChat_ACU(chatId, { reason: 'startup_restore' });
                await loadPresetAndCleanCharacterData_ACU();
                // 再次强制刷新数据和UI，确保初始加载时表格显示正确
                await loadAllChatMessages_ACU();
                // [provisional bridge] 启动加载当前聊天后统一恢复门：
                // 若上次运行崩溃留下 active provisional bridge（原 full 被暂存、临时根在链上），
                // 在首次读写前自动 finalize（有已提交 bucket）或 rollback（零提交）；
                // 无法证明安全时记录错误并 fail-closed，避免在残留拓扑上继续写入。
                const bridgeGate = await ensureNoActiveProvisionalBridgeForCurrentScope_ACU();
                if (!bridgeGate.ok) {
                    logError_ACU(`[ManualCatchUpBridge] 启动恢复残留 provisional bridge 失败：${bridgeGate.error}`);
                }
                // 阶段 D：启动补偿同样收敛为“一轮 merged refresh → snapshot hydrate”。
                // 老卡（有聊天历史）从聊天记录合并数据建表；新卡（无数据）由 refresh
                // 走 guide/模板基底，hydrate 失败或 degraded 时回退冷 reload。
                const refreshResult = await refreshMergedDataAndNotifyWithUI_ACU();
                if (isSqliteMode()) {
                    const envelope = refreshResult
                        && !refreshResult.degraded
                        && refreshResult.mergedData
                        ? createCanonicalSnapshotEnvelope_ACU({
                            data: refreshResult.mergedData,
                            chatIdentity: String(currentChatFileIdentifier_ACU || ''),
                            isolationKey: getCurrentIsolationKey_ACU(),
                            storageMode: 'sqlite',
                            lifecycleEpoch: getRuntimeLifecycleEpoch_ACU(),
                            source: 'merged_refresh',
                        })
                        : null;
                    if (envelope) {
                        logDebug_ACU('[SQLite] initWithChatId: 用 canonical snapshot hydrate 内存数据库...');
                        const hydrated = await hydrateStorageProviderFromSnapshot_ACU(envelope);
                        if (hydrated.ok) {
                            logDebug_ACU('[SQLite] initWithChatId: snapshot hydrate 完成');
                        }
                        else if (hydrated.failureCode === 'stale_load_discarded') {
                            logDebug_ACU('[SQLite] initWithChatId: snapshot 身份漂移，回退冷 reload。');
                            try {
                                await reloadStorageProvider();
                            }
                            catch (e) {
                                logError_ACU(`[SQLite] initWithChatId: 冷 reload 失败: ${e?.message}`);
                            }
                        }
                        else {
                            logError_ACU(`[SQLite] initWithChatId: snapshot hydrate 失败: ${hydrated.failureCode || 'unknown'}${hydrated.error ? `: ${hydrated.error}` : ''}`);
                        }
                    }
                    else {
                        logDebug_ACU('[SQLite] initWithChatId: merged refresh 未产出可用 canonical（degraded/空数据），回退冷 reload。');
                        try {
                            await reloadStorageProvider();
                        }
                        catch (e) {
                            logError_ACU(`[SQLite] initWithChatId: 数据库初始化失败: ${e?.message}`);
                        }
                    }
                }
                // S0-4：初始加载完成后捕获 checkpoint 保管库（删楼恢复的影子基线）。
                try {
                    captureCheckpointVaultForCurrentChat_ACU();
                }
                catch (e) {
                    logWarn_ACU(`[删楼守卫] initWithChatId 保管库捕获失败: ${e?.message}`);
                }
            };
            // C5 加载失败可见化：初始加载与 CHAT_CHANGED 同级兜底，不允许静默空表。
            const initWithChatIdSafely = async (chatId) => {
                try {
                    await initWithChatId(chatId);
                }
                catch (initError) {
                    const message = initError instanceof Error ? initError.message : String(initError);
                    logError_ACU('ACU: 初始加载表格数据失败（已尝试全部兼容读取层）:', initError);
                    showUiSurfaceToast_ACU({
                        kind: 'error',
                        text: `表格数据加载失败：${message}`,
                        action: {
                            label: '打开数据管理',
                            onClick: async () => { await getUiSurface_ACU()?.openSettings?.(); },
                        },
                    });
                }
            };
            if (SillyTavern_API_ACU && SillyTavern_API_ACU.chatId) {
                // chatId 已可用，延迟初始化
                setTimeout(async () => {
                    await initWithChatIdSafely(SillyTavern_API_ACU.chatId);
                }, 1000);
            }
            else {
                // chatId 暂时不可用，启动轮询重试（每200ms检查一次，最多等15秒）
                logWarn_ACU('ACU: chatId not available on initial load. Starting polling...');
                let pollCount = 0;
                const maxPolls = 75; // 200ms × 75 = 15秒
                const pollTimer = setInterval(async () => {
                    pollCount++;
                    const chatId = SillyTavern_API_ACU?.chatId;
                    if (chatId) {
                        clearInterval(pollTimer);
                        logDebug_ACU(`ACU: chatId became available after ${pollCount * 200}ms polling: ${chatId}`);
                        await initWithChatIdSafely(chatId);
                    }
                    else if (pollCount >= maxPolls) {
                        clearInterval(pollTimer);
                        logWarn_ACU(`ACU: chatId still not available after ${maxPolls * 200}ms polling. Waiting for CHAT_CHANGED event.`);
                    }
                }, 200);
            }
        }
        else {
            const capabilityDiagnostics = formatHostCapabilities_ACU(getLastHostCapabilities_ACU());
            logError_ACU(`ACU: Failed to initialize. Core APIs not available on DOM ready. 宿主能力: ${capabilityDiagnostics}`);
            console.error(`数据库自动更新脚本初始化失败：核心API加载失败。宿主能力: ${capabilityDiagnostics}`);
        }
    }

    /**
     * presentation/bootstrap/api-groups/callback-api.ts
     * 回调管理 API — 表格更新和填表开始的回调注册/注销/通知
     */
    let isNotifyingTableUpdate_ACU = false;
    let hasPendingTableUpdateNotification_ACU = false;
    // 合并窗口内只要出现过一次未落盘通知，跟发就按未落盘告知（宁可保守，不虚报已落盘）。
    let pendingNotificationHasUnpersisted_ACU = false;
    function notifyTableUpdateCallbacksOnce_ACU(ctx, meta) {
        const callbacksSnapshot = [...ctx.tableUpdateCallbacks];
        const callbackCount = callbacksSnapshot.length;
        logDebug_ACU(`Notifying ${callbackCount} callbacks about table update (persisted=${meta.persisted}).`);
        if (callbackCount === 0)
            return;
        // 修复：确保回调函数永远不会收到 null，而是收到一个空对象，增加稳健性。
        const dataToSend = currentJsonTableData_ACU || {};
        callbacksSnapshot.forEach((callback, callbackIndex) => {
            try {
                // 将最新的数据与元信息作为参数传给回调；旧回调只声明一个参数时第二参数被自然忽略。
                callback(dataToSend, meta);
            }
            catch (e) {
                logError_ACU('[回调管理] Error executing a table update callback:', {
                    callbackIndex,
                    callbackName: callback?.name || 'anonymous',
                    callbackCount,
                    error: e,
                });
            }
        });
    }
    function notifyTableUpdateCallbacksSafely_ACU(ctx, meta) {
        if (isNotifyingTableUpdate_ACU) {
            hasPendingTableUpdateNotification_ACU = true;
            if (!meta.persisted)
                pendingNotificationHasUnpersisted_ACU = true;
            logDebug_ACU('[回调管理] Table update notification is already running; queued one coalesced follow-up notification.');
            return;
        }
        isNotifyingTableUpdate_ACU = true;
        try {
            hasPendingTableUpdateNotification_ACU = false;
            pendingNotificationHasUnpersisted_ACU = false;
            notifyTableUpdateCallbacksOnce_ACU(ctx, meta);
            if (hasPendingTableUpdateNotification_ACU) {
                hasPendingTableUpdateNotification_ACU = false;
                const followUpMeta = { persisted: !pendingNotificationHasUnpersisted_ACU };
                pendingNotificationHasUnpersisted_ACU = false;
                notifyTableUpdateCallbacksOnce_ACU(ctx, followUpMeta);
            }
        }
        finally {
            isNotifyingTableUpdate_ACU = false;
        }
    }
    function createCallbackApi(ctx) {
        return {
            // 注册表格更新回调
            registerTableUpdateCallback: function (callback) {
                if (typeof callback === 'function' && !ctx.tableUpdateCallbacks.includes(callback)) {
                    ctx.tableUpdateCallbacks.push(callback);
                    logDebug_ACU('A new table update callback has been registered.');
                }
            },
            // 注销表格更新回调
            unregisterTableUpdateCallback: function (callback) {
                const index = ctx.tableUpdateCallbacks.indexOf(callback);
                if (index > -1) {
                    ctx.tableUpdateCallbacks.splice(index, 1);
                    logDebug_ACU('A table update callback has been unregistered.');
                }
            },
            // 内部使用：通知更新；meta.persisted=false 表示本次更新未写入聊天持久化（默认按已落盘处理）
            _notifyTableUpdate: function (meta) {
                notifyTableUpdateCallbacksSafely_ACU(ctx, { persisted: meta?.persisted !== false });
            },
            // 注册"填表开始"回调
            registerTableFillStartCallback: function (callback) {
                if (typeof callback === 'function' && !ctx.tableFillStartCallbacks.includes(callback)) {
                    ctx.tableFillStartCallbacks.push(callback);
                    logDebug_ACU('A new table fill start callback has been registered.');
                }
            },
            // 内部使用：通知"填表开始"
            _notifyTableFillStart: function () {
                const callbackCount = ctx.tableFillStartCallbacks.length;
                logDebug_ACU(`Notifying ${callbackCount} callbacks about table fill start.`);
                ctx.tableFillStartCallbacks.forEach((callback, callbackIndex) => {
                    try {
                        callback();
                    }
                    catch (e) {
                        logError_ACU('[回调管理] Error executing a table fill start callback:', {
                            callbackIndex,
                            callbackName: callback?.name || 'anonymous',
                            callbackCount,
                            error: e,
                        });
                    }
                });
            },
        };
    }

    function resolveLatestAiMessageIndex_ACU() {
        const chat = getChatArray_ACU();
        if (!Array.isArray(chat) || chat.length === 0)
            return -1;
        for (let i = chat.length - 1; i >= 0; i -= 1) {
            if (chat[i] && !chat[i].is_user)
                return i;
        }
        return -1;
    }
    function hasV2FullCheckpointAtOrBeforeTarget_ACU(targetMessageIndex, isolationKey) {
        const chat = getChatArray_ACU();
        if (!Array.isArray(chat) || targetMessageIndex < 0)
            return false;
        return chat.slice(0, targetMessageIndex + 1).some(message => {
            const tagData = readIsolatedTagData_ACU(message, isolationKey);
            return isV2TagData_ACU(tagData) && tagData.storageFrame.checkpoint?.kind === 'full';
        });
    }
    async function importTableJsonThroughCommit_ACU(jsonString, options = {}) {
        let newData;
        try {
            newData = JSON.parse(jsonString);
        }
        catch (error) {
            const message = error instanceof Error ? error.message : String(error);
            return {
                success: false,
                persisted: false,
                failureStage: 'input',
                issues: [{ code: 'import_invalid_json', message }],
                error: `导入的JSON无法解析：${message}`,
            };
        }
        if (!newData || typeof newData !== 'object' || !('mate' in newData) || !Object.keys(newData).some(k => k.startsWith('sheet_'))) {
            return {
                success: false,
                persisted: false,
                failureStage: 'input',
                issues: [{ code: 'import_invalid_structure', message: '导入的JSON缺少关键结构 (mate, sheet_*)。' }],
                error: '导入的JSON缺少关键结构 (mate, sheet_*)。',
            };
        }
        const importedTableData = sanitizeChatSheetsObject_ACU(newData, { ensureMate: true });
        const persist = options.persist !== false;
        if (!persist) {
            const provider = getStorageProvider();
            if (typeof provider.replaceAllData !== 'function') {
                return { success: false, persisted: false, failureStage: 'runtime_restore', error: '当前存储 provider 不支持全量替换命令。' };
            }
            const replaceResult = await provider.replaceAllData(importedTableData);
            if (!replaceResult.success) {
                return { success: false, persisted: false, failureStage: 'runtime_restore', error: replaceResult.error || '运行时全量替换失败。' };
            }
            const runtimeData = (provider.getCurrentData() || importedTableData);
            const sheetKeys = Object.keys(runtimeData).filter(k => k.startsWith('sheet_'));
            const hasSummaryTables = Object.keys(runtimeData)
                .filter(k => k.startsWith('sheet_'))
                .some(k => {
                const table = runtimeData?.[k];
                return Boolean(table?.name && isSummaryOrOutlineTable_ACU(table.name));
            });
            return {
                success: true,
                tableData: runtimeData,
                sheetKeys,
                hasSummaryTables,
                persisted: false,
            };
        }
        const audit = auditTableDataForUpgrade_ACU(importedTableData);
        const repair = repairTableDataFromAudit_ACU(audit);
        if (audit.status === 'unrecoverable' || repair.requiresConfirmation) {
            const diagnostics = audit.issues.map(issue => issue.code).join(', ') || audit.status;
            return {
                success: false,
                persisted: false,
                failureStage: 'preflight',
                auditStatus: audit.status,
                issues: audit.issues,
                error: `导入数据需要人工确认或无法修复：${diagnostics}`,
            };
        }
        const candidateData = repair.candidateData;
        if (isSqliteMode()) {
            const sqlitePreflight = await validateSqliteTemplateDataStrict_ACU(candidateData, { allowRuntimeDdlFallback: true });
            if (!sqlitePreflight.success) {
                const message = sqlitePreflight.error || '候选数据无法通过 SQLite hydrate。';
                return {
                    success: false,
                    persisted: false,
                    failureStage: 'preflight',
                    auditStatus: audit.status,
                    issues: [{ code: 'sqlite_preflight_failed', message }],
                    error: `导入候选数据未通过 SQLite 预检：${message}`,
                };
            }
        }
        else {
            logDebug_ACU('[TableImport] 当前为 native 存储模式，跳过 SQLite hydrate 预检。');
        }
        const sheetKeys = Object.keys(candidateData).filter(k => k.startsWith('sheet_'));
        const targetMessageIndex = resolveLatestAiMessageIndex_ACU();
        const commitResult = await runTableUpdateCommit_ACU({
            source: 'import',
            reason: 'importTableAsJson',
            isolationKey: getCurrentIsolationKey_ACU(),
            writeSet: [{ kind: 'all' }],
            revisionWriteSet: [{ kind: 'all' }],
            initialData: currentJsonTableData_ACU,
            targetMessageIndex,
            targetSheetKeys: sheetKeys,
            updateGroupKeys: null,
            trackingSheetKeys: [],
            trackAsUpdate: false,
            strictSave: true,
        }, async () => {
            const hasExistingAnchor = hasV2FullCheckpointAtOrBeforeTarget_ACU(targetMessageIndex, getCurrentIsolationKey_ACU());
            return {
                success: true,
                value: true,
                tableData: candidateData,
                persist: {
                    operations: hasExistingAnchor
                        ? [{ kind: 'data_replace', data: candidateData, reason: 'import' }]
                        : [],
                },
            };
        });
        if (!commitResult.success || !commitResult.tableData) {
            return {
                success: false,
                persisted: false,
                failureStage: 'commit',
                error: commitResult.error || '导入数据提交失败。',
            };
        }
        const provider = getStorageProvider();
        if (typeof provider.replaceAllData !== 'function') {
            await reloadStorageProvider();
            return { success: false, persisted: true, failureStage: 'post_commit_runtime', error: '导入数据已保存，但当前存储 provider 不支持运行时全量替换；已尝试重新加载运行时。' };
        }
        try {
            const replaceResult = await provider.replaceAllData(commitResult.tableData);
            if (!replaceResult.success) {
                await reloadStorageProvider();
                return { success: false, persisted: true, failureStage: 'post_commit_runtime', error: `导入数据已保存，但运行时全量替换失败；已尝试重新加载运行时：${replaceResult.error || '未知错误'}` };
            }
        }
        catch (error) {
            await reloadStorageProvider();
            return { success: false, persisted: true, failureStage: 'post_commit_runtime', error: `导入数据已保存，但运行时全量替换异常；已尝试重新加载运行时：${error instanceof Error ? error.message : String(error)}` };
        }
        const hasSummaryTables = Object.keys(commitResult.tableData)
            .filter(k => k.startsWith('sheet_'))
            .some(k => {
            const table = commitResult.tableData?.[k];
            return Boolean(table?.name && isSummaryOrOutlineTable_ACU(table.name));
        });
        return {
            success: true,
            messageIndex: commitResult.messageIndex ?? targetMessageIndex,
            tableData: commitResult.tableData,
            sheetKeys,
            hasSummaryTables,
            persisted: true,
        };
    }

    /**
     * presentation/bootstrap/api-groups/core-data-api.ts
     * 核心数据操作 API — exportTableAsJson / importTableAsJson / triggerUpdate
     */
    function shouldPersistImportedTableJson_ACU(options) {
        if (!options || typeof options !== 'object')
            return true;
        if (options.persist === false || options.runtimeOnly === true)
            return false;
        const mode = String(options.mode || options.source || '').toLowerCase();
        return !(mode === 'restore' || mode === 'runtime' || mode === 'runtime-only' || mode === 'delete-layer-restore');
    }
    function createCoreDataApi(ctx) {
        return {
            // 导出当前表格数据
            exportTableAsJson: function () {
                return currentJsonTableData_ACU || {};
            },
            // 导入并覆盖当前表格数据；默认外部导入会持久化，传 { persist:false } / { mode:'restore' } 时仅恢复运行时。
            importTableAsJson: async function (jsonString, options) {
                if (typeof jsonString !== 'string' || jsonString.trim() === '') {
                    logError_ACU('importTableAsJson received invalid input.');
                    showToastr_ACU('error', '导入数据失败：输入为空。');
                    return false;
                }
                try {
                    const persist = shouldPersistImportedTableJson_ACU(options);
                    const commitResult = await importTableJsonThroughCommit_ACU(jsonString, { persist });
                    if (commitResult.success) {
                        if (persist) {
                            const targetMessageIndexForVectorSync = commitResult.messageIndex ?? -1;
                            logDebug_ACU(`[importTableAsJson] 已通过服务层导入提交入口导入表格数据，messageIndex=${targetMessageIndexForVectorSync}。`);
                            await refreshMergedDataAndNotifyWithUI_ACU();
                            const sourceTableKey = Object.keys(commitResult.tableData || {}).find((sheetKey) => {
                                const table = commitResult.tableData?.[sheetKey];
                                return sheetKey.startsWith('sheet_') && !!table?.name && isSummaryOrOutlineTable_ACU(String(table.name));
                            });
                            if (sourceTableKey && getCurrentWorldbookConfig_ACU().summaryVectorIndexModeEnabled === true) {
                                try {
                                    const queueResult = await enqueueSummaryVectorIndexFlush_ACU({
                                        sourceTableKey,
                                        reason: 'importTableAsJson',
                                    });
                                    if (!queueResult.queued && !queueResult.skipped) {
                                        logWarn_ACU(`[importTableAsJson] 交火向量索引防抖归档入队失败: reason=${queueResult.reason || 'unknown'}`);
                                    }
                                    else {
                                        logDebug_ACU(`[importTableAsJson] 交火向量索引防抖归档已入队: queued=${queueResult.queued}, reason=${queueResult.reason || 'ok'}`);
                                    }
                                }
                                catch (syncError) {
                                    logError_ACU('[importTableAsJson] 交火向量索引防抖归档入队异常（表格导入已完成）:', syncError);
                                }
                            }
                        }
                        else {
                            logDebug_ACU('[importTableAsJson] 已按运行时恢复模式导入表格数据，未写入聊天持久化。');
                            topLevelWindow_ACU.AutoCardUpdaterAPI?._notifyTableUpdate?.({ persisted: false });
                        }
                        return true;
                    }
                    else {
                        throw new Error(commitResult.error || '导入数据提交失败。');
                    }
                }
                catch (error) {
                    logError_ACU('Failed to import table data from JSON:', error);
                    showToastr_ACU('error', `导入数据失败: ${error?.message || String(error)}`);
                    return false;
                }
            },
            // 删除楼层/备份恢复专用：只恢复运行时数据，不制造新的 V2 data_replace/checkpoint/log。
            restoreTableAsJson: async function (jsonString) {
                return this.importTableAsJson(jsonString, { mode: 'restore', persist: false });
            },
            // 外部触发增量更新
            triggerUpdate: async function () {
                logDebug_ACU('External trigger for database update received.');
                if (isAutoUpdatingCard_ACU) {
                    showToastr_ACU('info', '已有更新任务在后台进行中。', { acuToastCategory: ACU_TOAST_CATEGORY_ACU.MANUAL_TABLE });
                    return false;
                }
                _set_isAutoUpdatingCard_ACU(true);
                try {
                    await loadAllChatMessages_ACU();
                    const chatHistory = SillyTavern_API_ACU.chat || [];
                    const currentThreshold = getEffectiveAutoUpdateThreshold_ACU('manual_update');
                    const allAiMessageIndices = chatHistory
                        .map((msg, index) => !msg.is_user ? index : -1)
                        .filter((index) => index !== -1);
                    const numberOfAiMessages = allAiMessageIndices.length;
                    let sliceStartIndex = 0;
                    if (numberOfAiMessages > currentThreshold) {
                        const firstRelevantAiMessageMapIndex = numberOfAiMessages - currentThreshold;
                        const previousAiMessageMapIndex = firstRelevantAiMessageMapIndex - 1;
                        if (previousAiMessageMapIndex >= 0) {
                            sliceStartIndex = allAiMessageIndices[previousAiMessageMapIndex] + 1;
                        }
                    }
                    if (sliceStartIndex > 0 &&
                        chatHistory[sliceStartIndex] &&
                        !chatHistory[sliceStartIndex].is_user &&
                        chatHistory[sliceStartIndex - 1] &&
                        chatHistory[sliceStartIndex - 1].is_user) {
                        sliceStartIndex = sliceStartIndex - 1;
                        logDebug_ACU(`Adjusted slice start index to ${sliceStartIndex} to include preceding user message.`);
                    }
                    const messagesToProcess = chatHistory.slice(sliceStartIndex);
                    return await proceedWithCardUpdate_ACU(messagesToProcess);
                }
                catch (error) {
                    logError_ACU('triggerUpdate failed:', error);
                    return false;
                }
                finally {
                    _set_isAutoUpdatingCard_ACU(false);
