    /**
     * 为一条日志匹配处理建议。只对 error 级日志给建议；warn / debug 返回 null。
     */
    function resolveLogErrorHint(entry) {
        if (entry.level !== 'error')
            return null;
        const haystack = `${entry.tag} ${entry.message}`.toLowerCase();
        for (const rule of RULES) {
            const matched = typeof rule.test === 'function' ? rule.test(haystack) : rule.test.test(haystack);
            if (matched)
                return { id: rule.id, summary: rule.summary, steps: rule.steps };
        }
        return null;
    }
    /** 供测试与调试使用：规则 ID 列表（按匹配优先级排序）。 */
    const LOG_ERROR_HINT_RULE_IDS = RULES.map(rule => rule.id);

    /**
     * useLogViewer — 运行日志页业务流编排
     *
     * 页面只消费本 composable；日志读写集中对接 shared/log-buffer，避免 v2
     * Vue 组件复用旧 presentation/log-viewer 的 jQuery 状态机。
     */
    const levelOptions = [
        { value: 'all', label: '全部级别' },
        { value: 'debug', label: 'Debug' },
        { value: 'warn', label: 'Warn' },
        { value: 'error', label: 'Error' },
    ];
    function downloadJson(filename, data) {
        const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
        const url = URL.createObjectURL(blob);
        const doc = getAcuHostDocument();
        const a = doc.createElement('a');
        a.href = url;
        a.download = filename;
        doc.body.appendChild(a);
        a.click();
        doc.body.removeChild(a);
        URL.revokeObjectURL(url);
    }
    function useLogViewer() {
        const toast = useToastStore();
        const { warnLogEnabled, setWarnLogEnabled } = useDevOptions();
        const logs = ref([]);
        const knownTags = ref([]);
        const totalCount = ref(0);
        const levelFilter = ref('all');
        const tagFilter = ref('all');
        const keyword = ref('');
        const paused = ref(false);
        const pendingEntries = ref([]);
        const autoScroll = ref(true);
        const debugLogEnabled = ref(false);
        const message = ref(null);
        let unsubscribe = null;
        let rafId = null;
        const tagOptions = computed(() => [
            { value: 'all', label: '全部模块' },
            ...knownTags.value.map(tag => ({ value: tag, label: tag })),
        ]);
        const filteredLogs = computed(() => {
            const needle = keyword.value.trim().toLowerCase();
            return logs.value.filter(entry => {
                if (levelFilter.value !== 'all' && entry.level !== levelFilter.value)
